#!/bin/bash
D=$(dirname "$0")/docs; M="docker exec otsi_bp_validate mysql -uroot -pbp_validate_only --default-character-set=utf8mb4 -B -N -e"
$M "SELECT c.TABLE_NAME,c.ORDINAL_POSITION,c.COLUMN_NAME,c.COLUMN_TYPE,c.IS_NULLABLE,COALESCE(c.COLUMN_DEFAULT,''),c.EXTRA,c.COLUMN_KEY,REPLACE(c.COLUMN_COMMENT,'\t',' '),COALESCE(t.TABLE_COMMENT,'') FROM information_schema.COLUMNS c JOIN information_schema.TABLES t ON t.TABLE_SCHEMA=c.TABLE_SCHEMA AND t.TABLE_NAME=c.TABLE_NAME WHERE c.TABLE_SCHEMA='otsi_owner_vie' AND t.TABLE_TYPE='BASE TABLE' ORDER BY c.TABLE_NAME,c.ORDINAL_POSITION" > $D/_cols.tsv 2>/dev/null
$M "SELECT k.TABLE_NAME,k.CONSTRAINT_NAME,GROUP_CONCAT(k.COLUMN_NAME ORDER BY k.ORDINAL_POSITION),k.REFERENCED_TABLE_NAME,GROUP_CONCAT(k.REFERENCED_COLUMN_NAME ORDER BY k.ORDINAL_POSITION),r.DELETE_RULE FROM information_schema.KEY_COLUMN_USAGE k JOIN information_schema.REFERENTIAL_CONSTRAINTS r ON r.CONSTRAINT_SCHEMA=k.CONSTRAINT_SCHEMA AND r.CONSTRAINT_NAME=k.CONSTRAINT_NAME WHERE k.TABLE_SCHEMA='otsi_owner_vie' GROUP BY k.TABLE_NAME,k.CONSTRAINT_NAME,k.REFERENCED_TABLE_NAME,r.DELETE_RULE" > $D/_fks.tsv 2>/dev/null
$M "SELECT TABLE_NAME,INDEX_NAME,NON_UNIQUE,INDEX_TYPE,GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA='otsi_owner_vie' GROUP BY TABLE_NAME,INDEX_NAME,NON_UNIQUE,INDEX_TYPE" > $D/_idx.tsv 2>/dev/null
$M "SELECT t.TABLE_NAME,c.CONSTRAINT_NAME,REPLACE(REPLACE(c.CHECK_CLAUSE,'\n',' '),'\t',' ') FROM information_schema.TABLE_CONSTRAINTS t JOIN information_schema.CHECK_CONSTRAINTS c ON c.CONSTRAINT_SCHEMA=t.CONSTRAINT_SCHEMA AND c.CONSTRAINT_NAME=t.CONSTRAINT_NAME WHERE t.TABLE_SCHEMA='otsi_owner_vie' AND t.CONSTRAINT_TYPE='CHECK'" > $D/_chk.tsv 2>/dev/null
